  1	// Movement engine: owns the tick loop, coordinates drag sampling, throw/fall
  2	// physics, and dispatches to the active movement mode.
  3	
  4	import { invoke } from "@tauri-apps/api/core";
  5	import type { Pet } from "../pet";
  6	import { fetchEnvironment } from "./environment";
  7	import { runMode } from "./modes";
  8	import {
  9	  applyFall,
 10	  applyThrow,
 11	  cancelThrow,
 12	  clearSamples,
 13	  isThrowing,
 14	  recordSample,
 15	  releaseVelocity,
 16	} from "./physics";
 17	import type { Config, Environment, RoamMode } from "./types";
 18	import {
 19	  SLEEP_AFTER_MS,
 20	  SLEEP_ROW_DEFAULT,
 21	  THROW_MIN_SPEED,
 22	  TICK_MS,
 23	  clampToBounds,
 24	  loadConfig,
 25	  sleep,
 26	} from "./types";
 27	import { currentLogicalPos, setLogical, setNativeDragTracking } from "./window";
 28	
 29	/// Tick delay when the pet is resting / sleeping / stationary. The active
 30	/// TICK_MS (30ms) is only needed while the pet is actually moving — resting
 31	/// states (restUntil, sleep, stay mode) only need to check periodically whether
 32	/// to wake up. 200ms cuts IPC calls from 33/sec to 5/sec while idle, with no
 33	/// visible change (the pet resumes walking within one idle-tick of restUntil
 34	/// expiring, imperceptible for a desktop companion).
 35	const IDLE_TICK_MS = 200;
 36	
 37	let petRef: Pet | null = null;
 38	let dragging = false;
 39	let releasePending = false;
 40	let stopRequested = false;
 41	
 42	/// Mood drives two behaviors: pause roaming while the user needs to read the
 43	/// bubble (waiting / celebrate), and let the pet doze off when idle.
 44	let mood: string = "idle";
 45	let lastMoveTs = Date.now();
 46	let sleeping = false;
 47	
 48	/// Moods that freeze the pet so the bubble / celebration animation stays readable.
 49	const MOOD_PAUSES_ROAM = new Set(["waiting", "celebrate"]);
 50	
 51	function stop(): boolean { return stopRequested; }
 52	
 53	/// Called from main.ts after each mood evaluation. Non-idle moods wake the pet.
 54	export function setMood(m: string): void {
 55	  mood = m;
 56	  if (m !== "idle") wake();
 57	}
 58	
 59	function wake(): void {
 60	  if (!sleeping) return;
 61	  sleeping = false;
 62	  petRef?.clearRow();
 63	}
 64	
 65	function enterSleep(): void {
 66	  if (sleeping) return;
 67	  sleeping = true;
 68	  const bound = parseInt(localStorage.getItem("ap_bind_sleep") ?? "", 10);
 69	  const row = Number.isFinite(bound) && bound >= 0 ? bound : SLEEP_ROW_DEFAULT;
 70	  petRef?.setRow(row);
 71	}
 72	
 73	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 74	/// Returns true when the pet is actively moving/interacting and needs the fast
 75	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 76	/// idle (200ms) tick and skip most IPC calls.
 77	async function tick(): Promise<boolean> {
 78	  if (isThrowing()) return true;
 79	  if (dragging) {
 80	    const pos = await currentLogicalPos();
 81	    if (pos) recordSample(pos);
 82	    return true;
 83	  }
 84	  if (releasePending) {
 85	    releasePending = false;
 86	    const vel = releaseVelocity();
 87	    clearSamples();
 88	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 89	      wake();
 90	      await handleDragRelease(vel);
 91	      return true;
 92	    }
 93	  }
 94	
 95	  // Mood-driven freeze: keep the pet still while the user needs to see the
 96	  // bubble or the celebrate burst. Throws and drags above still work.
 97	  if (MOOD_PAUSES_ROAM.has(mood)) {
 98	    wake();
 99	    petRef?.clearRow();
100	    return false;
101	  }
102	
103	  const cfg = loadConfig();
104	  if (!cfg.enabled || cfg.mode === "stay") {
105	    handleStationary();
106	    return false;
107	  }
108	
109	  wake();
110	  const moved = await stepMode(cfg.mode);
111	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
112	    enterSleep();
113	  }
114	  return moved;
115	}
116	
117	/// Run one mode step and apply it. Returns true if the pet actually moved.
118	async function stepMode(mode: RoamMode): Promise<boolean> {
119	  const env = await fetchEnvironment(mode === "climb");
120	  if (!env) return false;
121	  const pos = await currentLogicalPos();
122	  if (!pos) return false;
123	
124	  const next = await runMode(mode, { env, pos, pet: petRef });
125	  const clamped = clampToBounds(next, env.workArea);
126	  if (Math.abs(clamped.x - pos.x) < 0.5 && Math.abs(clamped.y - pos.y) < 0.5) {
127	    return false;
128	  }
129	  lastMoveTs = Date.now();
130	  try { await setLogical(clamped); }
131	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
132	  return true;
133	}
134	
135	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
136	function handleStationary(): void {
137	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
138	    enterSleep();
139	  } else {
140	    wake();
141	    petRef?.clearRow();
142	  }
143	}
144	
145	type ReleaseContext = {
146	  config: Config;
147	  environment: Environment;
148	};
149	
150	type ConfigReader = () => Config;
151	type EnvironmentReader = (includeSystemWindows: boolean) => Promise<Environment | null>;
152	
153	export async function resolveReleaseContext(
154	  getConfig: ConfigReader = loadConfig,
155	  getEnvironment: EnvironmentReader = fetchEnvironment,
156	): Promise<ReleaseContext | null> {
157	  let config = getConfig();
158	  const includedSystemWindows = config.mode === "climb";
159	  let environment = await getEnvironment(includedSystemWindows);
160	  if (!environment) return null;
161	
162	  config = getConfig();
163	  if (config.mode === "climb" && !includedSystemWindows) {
164	    environment = await getEnvironment(true);
165	    if (!environment) return null;
166	  }
167	
168	  return { config: getConfig(), environment };
169	}
170	
171	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
172	  const context = await resolveReleaseContext();
173	  if (!context) return;
174	  const { config: cfg, environment: env } = context;
175	
176	  if (cfg.mode === "climb" && env.windows.length > 0) {
177	    const surfaces = env.windows.map((w) => w.rect);
178	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
179	  } else {
180	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
181	  }
182	}
183	
184	async function loop(): Promise<void> {
185	  while (!stopRequested) {
186	    const active = await tick();
187	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
188	  }
189	  petRef?.clearRow();
190	}
191	
192	export function initEngine(pet: Pet): void {
193	  if (petRef) return;
194	  petRef = pet;
195	  stopRequested = false;
196	  lastMoveTs = Date.now();
197	  mood = "idle";
198	  sleeping = false;
199	  void loop();
200	}
201	
202	export function destroyEngine(): void {
203	  stopRequested = true;
204	  cancelThrow();
205	  petRef = null;
206	}
207	
208	export function setDragging(isDragging: boolean): void {
209	  dragging = isDragging;
210	  setNativeDragTracking(isDragging);
211	  if (isDragging) {
212	    cancelThrow();
213	    clearSamples();
214	    wake();
215	    releasePending = false;
216	  } else if (petRef) {
217	    releasePending = true;
218	  }
219	}

