   302	        .title("DesktopPet")
   303	        .inner_size(260.0, 320.0)
   304	        .transparent(true)
   305	        .decorations(false)
   306	        .always_on_top(true)
   307	        .skip_taskbar(true)
   308	        .resizable(false)
   309	        .shadow(false)
   310	        .focused(false)
   311	        .visible(instance.visible && read_desktop_pets_visible());
