   269	fn logical_position_for_physical(app: &tauri::AppHandle, x: i32, y: i32) -> (f64, f64) {
   270	    let scale_factor = app.available_monitors()
   271	        .ok()
   272	        .and_then(|monitors| monitors.into_iter().find(|monitor| {
   273	            let position = monitor.position();
   274	            let size = monitor.size();
   275	            x >= position.x
   276	                && x < position.x + size.width as i32
   277	                && y >= position.y
   278	                && y < position.y + size.height as i32
   279	        }))
   280	        .map(|monitor| monitor.scale_factor())
   281	        .unwrap_or(1.0);
   282	    (x as f64 / scale_factor, y as f64 / scale_factor)
   283	}
